import { EditableBlockData } from './BlockIframeData';
/**
 * The event that the embedded application sends to Storyblok's Visual Editor via `Window.postMessage`.
 * The type is a discriminated union where the `action` property is the discriminator.
 */
export type BridgeAction = NoFocusBridgeAction | InitializedBridgeAction | EditBridgeAction | AddBlockBeforeBridgeAction | AddBlockAfterBridgeAction | MoveBackwardBridgeAction | MoveForwardBridgeAction | DeleteBlockBridgeAction | CopyBridgeAction | PingBridgeAction;
export type NoFocusBridgeAction = {
    action: 'noFocus';
};
export type InitializedBridgeAction = {
    action: 'initialized';
};
export type EditBridgeAction = {
    action: 'edit';
    dataC: EditableBlockData;
};
export type AddBlockBeforeBridgeAction = {
    action: 'addBlockBefore';
    blok: {
        _parentUid: string;
        _parentfield: string;
        _parentName: string;
        _parentindex: number;
    };
};
export type AddBlockAfterBridgeAction = {
    action: 'addBlockAfter';
    blok: {
        _parentUid: string;
        _parentfield: string;
        _parentName: string;
        _parentindex: number;
    };
};
export type MoveBackwardBridgeAction = {
    action: 'moveBackward';
    blok: {
        _uid: string;
        _parentUid: string;
        _parentfield: string;
    };
};
export type MoveForwardBridgeAction = {
    action: 'moveForward';
    blok: {
        _uid: string;
        _parentUid: string;
        _parentfield: string;
    };
};
export type DeleteBlockBridgeAction = {
    action: 'deleteBlock';
    blok: {
        _uid: string;
        _parentUid: string;
        _parentfield: string;
    };
};
export type CopyBridgeAction = {
    action: 'copy';
    blok: {
        _uid: string;
    };
};
export type PingBridgeAction = {
    action: 'ping';
};
